 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Insert a full-width color-3 line into the blank row separating the two shapes.
    for r in range(1, h - 1):
        if all(v == 0 for v in grid[r]) and any(grid[r - 1]) and any(grid[r + 1]):
            out[r] = [3] * w
    return out
